import json, hashlib, subprocess, os
from pathlib import Path

source=Path("/Users/steventran/do-again")
projects=[Path("/Users/steventran/jobpipe"),Path("/Users/steventran/Sonary")]

def run(cwd,args,env=None):
    p=subprocess.run(args,cwd=cwd,text=True,capture_output=True,check=False,env=env)
    return p

def read_json(p):
    try:
        v=json.loads(p.read_text())
        return v if isinstance(v,dict) else {}
    except Exception:
        return {}

def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None

def tree_hash(package):
    h=hashlib.sha256()
    for p in sorted(x for x in package.rglob("*") if x.is_file()):
        rel=p.relative_to(package).as_posix().encode()
        h.update(len(rel).to_bytes(4,"big")); h.update(rel)
        data=p.read_bytes()
        h.update(len(data).to_bytes(8,"big")); h.update(data)
    return h.hexdigest()

source_pkg=source/"src/do_again"
source_hash=tree_hash(source_pkg)
rows=[]
for repo in projects:
    key=hashlib.sha256(str(repo.resolve()).encode()).hexdigest()[:12]
    root=Path.home()/".do_again/projects"/key
    runtime=root/"runtime/do_again"
    state=root/"state"
    journal=read_json(state/"runtime_upgrade.json")
    browser=read_json(state/"browser_status.json")
    live=read_json(state/"liveness.json")
    cfg=(repo/"do-again.toml").read_text() if (repo/"do-again.toml").is_file() else ""
    status=run(repo,["git","status","--porcelain=v1"]).stdout
    service=run(source,["python3","-m","do_again.cli","status",str(repo)],env={**os.environ,"PYTHONPATH":str(source/"src")})
    rows.append({
      "repo":str(repo),
      "head":run(repo,["git","rev-parse","HEAD"]).stdout.strip(),
      "status":status,
      "source_tree_hash":source_hash,
      "runtime_tree_hash":tree_hash(runtime),
      "runtime_matches_source":tree_hash(runtime)==source_hash,
      "features":{
        "daemon":(runtime/"service/daemon.py").is_file(),
        "liveness":(runtime/"service/liveness.py").is_file(),
        "rollout":(runtime/"service/rollout.py").is_file(),
      },
      "feature_hashes":{
        "daemon":sha(runtime/"service/daemon.py"),
        "liveness":sha(runtime/"service/liveness.py"),
        "rollout":sha(runtime/"service/rollout.py"),
      },
      "source_feature_hashes":{
        "daemon":sha(source_pkg/"service/daemon.py"),
        "liveness":sha(source_pkg/"service/liveness.py"),
        "rollout":sha(source_pkg/"service/rollout.py"),
      },
      "upgrade_journal":journal,
      "browser_status":browser,
      "liveness_state":live,
      "continuous_config":"continuous = true" in cfg.lower(),
      "status_cli":{"rc":service.returncode,"stdout":service.stdout,"stderr":service.stderr},
    })

print(json.dumps(rows,indent=2,sort_keys=True))

for row in rows:
    if not row["runtime_matches_source"]:
        raise SystemExit(f"runtime tree mismatch: {row['repo']}")
    if not all(row["features"].values()):
        raise SystemExit(f"missing runtime feature: {row['repo']}")
    if row["feature_hashes"] != row["source_feature_hashes"]:
        raise SystemExit(f"feature hash mismatch: {row['repo']}")
print("JOBPIPE_SONARY_RUNTIME_ACCEPTANCE_OK")
